INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"Considerando as disposições do Código Civil acerca da incapacidade e da emancipação, julgue o item a seguir: O menor com dezesseis anos completos adquire a plena capacidade civil, tornando-se emancipado independentemente de homologação judicial ou consentimento paterno, caso venha a estabelecer-se em emprego público efetivo.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta. De acordo com o art. 5º, parágrafo único, inciso III, do Código Civil, a incapacidade cessará para os menores pelo exercício de emprego público efetivo. Trata-se de uma hipótese de emancipação legal, que opera-se de pleno direito com o preenchimento do requisito, sem depender de concordância dos pais ou decisão de um juiz.","difficulty":"media","tags":["Capacidade Civil","Emancipação legal","Emprego público"]}'::jsonb, 'draft', 'nzqotr', 0),
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"A respeito do instituto da comoriência e do fim da personalidade natural previstos no ordenamento jurídico pátrio, julgue o item subseqüente. Se duas pessoas falecerem em um mesmo desastre e não for possível verificar peritamente qual delas morreu primeiro, a lei brasileira adotará a presunção legal de que a pessoa mais velha faleceu antes da mais nova para fins de fixação da ordem sucessória.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva está errada. O ordenamento jurídico brasileiro adota o instituto da comoriência no art. 8º do Código Civil, que determina que se dois ou mais indivíduos falecerem na mesma ocasião, não se podendo averiguar se algum dos comorientes precedeu aos outros, presumir-se-ão simultaneamente mortos. Não há presunção de morte baseada na idade das vítimas no Brasil.","difficulty":"media","tags":["Comoriência","Morte Simultânea","Fim da Personalidade"]}'::jsonb, 'draft', 'ixezbi', 1),
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"Considerando o entendimento pacificado no Supremo Tribunal Federal e no Superior Tribunal de Justiça sobre os direitos da personalidade, julgue o próximo item. A alteração do prenome e do gênero da pessoa natural em seu assentamento no registro civil pode ser realizada de maneira direta em cartório, sendo dispensável a comprovação da realização de cirurgia de redesignação sexual e a prévia propositura de ação judicial para essa finalidade.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta. O STF (ADI 4275) e o STJ admitem a alteração de gênero e de prenome no registro civil diretamente pela via administrativa, ou seja, nos próprios cartórios. Exigir averiguação médica ou judicial e cirurgia de transgenitalização configuraria grave ofensa aos princípios da dignidade da pessoa humana e do livre desenvolvimento da personalidade.","difficulty":"media","tags":["Direitos da Personalidade","Alteração de Nome","Registro Civil","Transgêneros"]}'::jsonb, 'draft', 'j1nh', 2),
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"À luz do Código Civil, a declaração de morte presumida sem a decretação sucessiva de ausência é providência que somente será possível quando for extremamente provável a morte de indivíduo que estava em situação de iminente perigo de vida ou se, desaparecido em campanha militar, a pessoa não for localizada no decurso do prazo de dois anos contados a partir do fim da guerra.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta. Trata-se da exata previsão normativa delineada no art. 7º, incisos I e II, do Código Civil, que institui as exclusivas hipóteses permissivas para declaração da morte presumida de forma direta e sem ser necessário o longo procedimento prévio da ausência (curadoria, sucessão provisória e sucessão definitiva).","difficulty":"media","tags":["Morte Presumida","Extinção da Personalidade","Direito Civil"]}'::jsonb, 'draft', 'pizp96', 3),
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"Com a incorporação do Estatuto da Pessoa com Deficiência (Lei Brasileira de Inclusão) ao sistema normativo pátrio, a pessoa com deficiência intelectual passou a figurar, compulsoriamente, no rol dos relativamente incapazes para os atos da vida civil, dependendo de assistência para o exercício de seu direito ao casamento e à constituição de união estável.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva está errada. O Estatuto da Pessoa com Deficiência alterou o Código Civil para estabelecer que a deficiência não afeta a plena capacidade civil da pessoa, inclusive para casar-se e constituir união estável, bem como para exercer direitos sexuais e reprodutivos (art. 6º do EPD). Com a mudança, atualmente apenas os menores de 16 anos são tidos por absolutamente incapazes.","difficulty":"media","tags":["Capacidade Civil","Estatuto da Pessoa com Deficiência","Pessoas Naturais"]}'::jsonb, 'draft', 'ewsfpu', 4),
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"A jurisprudência sumulada do Superior Tribunal de Justiça estabelece que independe de prova do prejuízo a indenização pela publicação não autorizada de imagem de pessoa com fins econômicos ou comerciais, constituindo uma hipótese de responsabilização na modalidade de dano moral in re ipsa.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta. De fato, a Súmula 403 do STJ prevê explicitamente que: ''Independe de prova do prejuízo a indenização pela publicação não autorizada da imagem de pessoa com fins econômicos ou comerciais''. Como a lesão atinge diretamente um direito da personalidade (imagem) conjugado à exploração indevida de proveito, presume-se o dano.","difficulty":"media","tags":["Direito de Imagem","Direitos da Personalidade","Súmula 403 STJ"]}'::jsonb, 'draft', 'z7o588', 5),
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"O sistema civil brasileiro vigente encampa irrestritamente a teoria concepcionista a respeito do início da personalidade, o que significa que se reconhece ao nascituro a titularidade atual, perfeita e acabada de todos os gêneros de direitos patrimoniais, permitindo sua inscrição, desde logo e antes do nascimento, como detentor pleno do direito a herdar e receber doações definitivas.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva está errada. Apesar de a lei colocar a salvo, desde a concepção, os direitos do nascituro, o art. 2º do CC estabelece categoricamente que a personalidade civil da pessoa começa do nascimento com vida. Consequentemente, a titularidade de direitos patrimoniais (como a capacidade para suceder em herança ou receber doações) é ressalvada, mas sempre sujeita à condição suspensiva do nascimento com vida.","difficulty":"media","tags":["Nascituro","Início da Personalidade","Teorias Natalista e Concepcionista"]}'::jsonb, 'draft', 'x6cghv', 6),
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"Acerca dos fatos jurídicos que repercutem sobre a capacidade e a menoridade, a colação de grau pelo menor em ensino médio prestigiado constitui uma importante causa de emancipação legal estipulada no código, garantindo com que este se torne plenamente capaz para o desempenho de todos os atos da vida civil, em reconhecimento à sua maturidade educacional.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva está errada. O artigo 5º, parágrafo único, inciso II do Código Civil prevê que a incapacidade civil cessará (emancipação) não pela colação de grau em nível médio, mas sim precipuamente pela ''colação de grau em curso de ensino superior''.","difficulty":"facil","tags":["Capacidade","Emancipação legal","Maioridade"]}'::jsonb, 'draft', '65fvs1', 7),
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"Muito embora o princípio lógico afirme que os direitos da personalidade terminam, em regra, simultaneamente com a pessoa pela constatação de sua morte real cerebral, o Código Civil reconhece caráter translativo peculiar à tutela desses direitos, autorizando textualmente o cônjuge, descendente ou ascendente direto a pleitear indenização por grave ofensa propagada à honra ou imagem daquele que já é falecido.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta. A morte natural finda efetivamente a personalidade jurídica do indivíduo (art. 6 do CC). Todavia, o parágrafo único do art. 12 legitima as pessoas mais próximas e ligadas por afinidade (cônjuge, os ascendentes e descendentes) a adotarem medidas ou requerimentos judiciais com intuito de resguardarem o bom nome, intimidade e a memória do falecido, exigindo perdas e danos e fazendo cessar ofensa, consolidando o instituto da proteção post mortem.","difficulty":"media","tags":["Direitos da Personalidade","Proteção Post Mortem","Extinção da Personalidade"]}'::jsonb, 'draft', 'hd61ur', 8),
('e1445d06-0adf-49d9-90de-9143b95959f8', '{"enunciado":"Em virtude de significativa inovação do ordenamento civil em defesa da infância e adolescência sob a atual perspectiva constitucional, é categoricamente proibido, em qualquer circunstância e abolindo-se antigas exceções, o casamento tutelado de indivíduo que ainda não tenha atingido a idade núbil mínima imposta pela lei (dezesseis anos), até mesmo em cenário de comprovada gravidez.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva está correta. A Lei n. 13.811/2019 suprimiu excepcionais permissões pretéritas do ordenamento, alterando pontualmente o artigo 1.520 do Código Civil. Hoje, não se permite o casamento perante a lei, em hipótese e cenário algum (incluindo gravidez ou visando evitar a imposição de penalidade criminal), de pessoa que possua menos de dezesseis anos de idade. Isso consagra de fato a intenção protetiva absoluta à menoridade.","difficulty":"media","tags":["Capacidade para Casar","Idade Núbil","Exceções à Capacidade"]}'::jsonb, 'draft', 'z7u93c', 9);